// ------------------------------------------------------------ infrastructure

type SharedTerminal = Rc<RefCell<TestTerminal>>;
type Clock = Rc<Cell<f64>>;

/// Memory pseudo terminal: `Vec<String>` output stream plus a programmable
/// input queue, mirroring the oracle's FakeTerminal.
#[derive(Default)]
struct TestTerminal {
    writes: Vec<String>,
    columns: usize,
    rows: usize,
    input_handler: Option<Box<dyn FnMut(String) + Send>>,
    resize_handler: Option<Box<dyn FnMut() + Send>>,
    start_calls: usize,
    stop_calls: usize,
}

impl TestTerminal {
    fn new(columns: usize, rows: usize) -> Self {
        Self {
            writes: Vec::new(),
            columns,
            rows,
            ..Default::default()
        }
    }

    fn send_input(&mut self, data: &str) {
        if let Some(handler) = &mut self.input_handler {
            handler(data.to_string());
        }
    }

    fn resize(&mut self, columns: usize, rows: usize) {
        self.columns = columns;
        self.rows = rows;
        if let Some(handler) = &mut self.resize_handler {
            handler();
        }
    }
}

impl Terminal for TestTerminal {
    fn start(
        &mut self,
        on_input: Box<dyn FnMut(String) + Send>,
        on_resize: Box<dyn FnMut() + Send>,
    ) {
        self.input_handler = Some(on_input);
        self.resize_handler = Some(on_resize);
        self.start_calls += 1;
    }

    fn stop(&mut self) {
        self.input_handler = None;
        self.resize_handler = None;
        self.stop_calls += 1;
    }

    fn write(&mut self, data: &str) {
        self.writes.push(data.to_string());
    }

    fn columns(&self) -> usize {
        self.columns
    }

    fn rows(&self) -> usize {
        self.rows
    }

    fn kitty_protocol_active(&self) -> bool {
        false
    }

    fn move_by(&mut self, _lines: i64) {}

    fn hide_cursor(&mut self) {
        self.writes.push("\x1b[?25l".to_string());
    }

    fn show_cursor(&mut self) {
        self.writes.push("\x1b[?25h".to_string());
    }

    fn clear_line(&mut self) {}
    fn clear_from_cursor(&mut self) {}
    fn clear_screen(&mut self) {}
    fn set_title(&mut self, _title: &str) {}
    fn set_progress(&mut self, _active: bool) {}
}

/// Script actions requested from inside `handleInput` (upstream closures call
/// `tui.setFocus(...)` re-entrantly; the driver applies these right after the
/// event and before any further input event — behaviorally identical because
/// the only thing the TUI does after `handleInput` is request the immediate
/// render).
enum ScriptAction {
    Focus(&'static str),
    FocusNull,
    Unfocus {
        overlay: OverlayHandle,
        /// None = no options; Some(None) = explicit null target;
        /// Some(Some(handle)) = named target.
        target: Option<Option<ComponentHandle>>,
    },
    RebuildBaseAndFocus {
        base: Rc<RefCell<Container>>,
        child: ComponentHandle,
    },
}

type ScriptFn = Box<dyn FnMut(&str) -> Vec<ScriptAction> + 'static>;
type MouseFn = Box<dyn FnMut(&TuiMouseEvent) -> TuiMouseEventResult + 'static>;

/// Focusable input-recording component (upstream FocusableOverlay and
/// friends) with an optional input script and mouse handler.
struct ScriptedOverlay {
    lines: Vec<String>,
    render_count: usize,
    inputs: Vec<String>,
    focused: bool,
    wants_key_release: bool,
    requested_width: Option<usize>,
    script: Option<ScriptFn>,
    mouse_handler: Option<MouseFn>,
    pending_actions: Vec<ScriptAction>,
    /// Upstream InputComponent: `handleInput` mirrors the data into lines.
    set_lines_on_input: bool,
}

impl ScriptedOverlay {
    fn new(lines: &[&str]) -> Self {
        Self {
            lines: lines.iter().map(|line| (*line).to_string()).collect(),
            render_count: 0,
            inputs: Vec::new(),
            focused: false,
            wants_key_release: false,
            requested_width: None,
            script: None,
            mouse_handler: None,
            pending_actions: Vec::new(),
            set_lines_on_input: false,
        }
    }

    fn take_pending_actions(&mut self) -> Vec<ScriptAction> {
        std::mem::take(&mut self.pending_actions)
    }

    fn set_lines(&mut self, lines: Vec<String>) {
        self.lines = lines;
    }
}

impl Component for ScriptedOverlay {
    fn render(&mut self, width: usize) -> Vec<String> {
        self.render_count += 1;
        self.requested_width = Some(width);
        self.lines.clone()
    }

    fn handle_input(&mut self, data: &str) {
        self.inputs.push(data.to_string());
        if self.set_lines_on_input {
            self.lines = vec![data.to_string()];
        }
        if let Some(script) = &mut self.script {
            self.pending_actions.extend(script(data));
        }
    }

    fn handle_mouse(&mut self, event: &TuiMouseEvent) -> Option<TuiMouseEventResult> {
        Some((self.mouse_handler.as_mut()?)(event))
    }

    fn is_focusable(&self) -> bool {
        true
    }

    fn focused(&self) -> bool {
        self.focused
    }

    fn set_focused(&mut self, focused: bool) {
        self.focused = focused;
    }

    fn wants_key_release(&self) -> bool {
        self.wants_key_release
    }
}

/// Non-focusable static-lines component (upstream StaticLines/StaticOverlay).
struct StaticLines {
    lines: Vec<String>,
    inputs: Vec<String>,
}

impl StaticLines {
    /// The forwarded input sequences (upstream InputRecorder.inputs).
    fn inputs(&self) -> Vec<String> {
        self.inputs.clone()
    }
}

impl Component for StaticLines {
    fn render(&mut self, _width: usize) -> Vec<String> {
        self.lines.clone()
    }

    fn handle_input(&mut self, data: &str) {
        self.inputs.push(data.to_string());
    }
}

struct EmptyContent;

impl Component for EmptyContent {
    fn render(&mut self, _width: usize) -> Vec<String> {
        Vec::new()
    }
}

fn scripted_handle(lines: &[&str]) -> (ComponentHandle, Rc<RefCell<ScriptedOverlay>>) {
    let (handle, shared) = ComponentHandle::with_shared(ScriptedOverlay::new(lines));
    (handle, shared)
}

fn static_handle(lines: &[&str]) -> (ComponentHandle, Rc<RefCell<StaticLines>>) {
    let (handle, shared) = ComponentHandle::with_shared(StaticLines {
        lines: lines.iter().map(|l| (*l).to_string()).collect(),
        inputs: Vec::new(),
    });
    (handle, shared)
}

/// The `doRender` reference implementation: tui-main-screen.ts `doRender`
/// core (non-Kitty paths, single buffered flush, no crash/debug logs).
struct ReferenceRenderer {
    previous_lines: Vec<String>,
    previous_width: i64,
    previous_height: i64,
    cursor_row: i64,
    hardware_cursor_row: i64,
    max_lines_rendered: usize,
    previous_viewport_top: i64,
    render_count: usize,
    last_new_lines: Vec<String>,
}

impl ReferenceRenderer {
    fn new() -> Self {
        Self {
            previous_lines: Vec::new(),
            previous_width: 0,
            previous_height: 0,
            cursor_row: 0,
            hardware_cursor_row: 0,
            max_lines_rendered: 0,
            previous_viewport_top: 0,
            render_count: 0,
            last_new_lines: Vec::new(),
        }
    }

    fn write(tui: &mut Tui, buffer: &str) {
        tui.terminal().borrow_mut().write(buffer);
    }

    fn position_hardware_cursor(
        &mut self,
        tui: &mut Tui,
        cursor_pos: Option<(usize, usize)>,
        total_lines: i64,
    ) {
        if cursor_pos.is_none() || total_lines <= 0 {
            tui.terminal().borrow_mut().hide_cursor();
            return;
        }
        let (row, col) = cursor_pos.expect("checked above");
        let target_row = (row as i64).clamp(0, total_lines - 1);
        let target_col = col as i64;
        let row_delta = target_row - self.hardware_cursor_row;
        let mut buffer = String::new();
        if row_delta > 0 {
            buffer.push_str(&format!("\x1b[{row_delta}B"));
        } else if row_delta < 0 {
            buffer.push_str(&format!("\x1b[{}A", -row_delta));
        }
        buffer.push_str(&format!("\x1b[{}G", target_col + 1));
        if !buffer.is_empty() {
            Self::write(tui, &buffer);
        }
        self.hardware_cursor_row = target_row;
        if tui.get_show_hardware_cursor() {
            tui.terminal().borrow_mut().show_cursor();
        } else {
            tui.terminal().borrow_mut().hide_cursor();
        }
    }

    fn full_render(
        &mut self,
        tui: &mut Tui,
        new_lines: &[String],
        width: i64,
        height: i64,
        clear: bool,
        cursor_pos: Option<(usize, usize)>,
    ) {
        tui.add_full_redraw();
        let mut buffer = String::from("\x1b[?2026h");
        if clear {
            buffer.push_str("\x1b[2J\x1b[H\x1b[3J");
        }
        for (i, line) in new_lines.iter().enumerate() {
            if i > 0 {
                buffer.push_str("\r\n");
            }
            buffer.push_str(line);
        }
        buffer.push_str("\x1b[?2026l");
        Self::write(tui, &buffer);
        self.cursor_row = (new_lines.len() as i64 - 1).max(0);
        self.hardware_cursor_row = self.cursor_row;
        if clear {
            self.max_lines_rendered = new_lines.len();
        } else {
            self.max_lines_rendered = self.max_lines_rendered.max(new_lines.len());
        }
        let buffer_length = (height as usize).max(new_lines.len());
        self.previous_viewport_top = buffer_length.saturating_sub(height as usize) as i64;
        self.position_hardware_cursor(tui, cursor_pos, new_lines.len() as i64);
        self.previous_lines = new_lines.to_vec();
        self.previous_width = width;
        self.previous_height = height;
    }

    fn do_render_impl(&mut self, tui: &mut Tui) {
        if tui.is_stopped() {
            return;
        }
        self.render_count += 1;
        let (width, height) = {
            let terminal = tui.terminal();
            let terminal = terminal.borrow();
            (terminal.columns() as i64, terminal.rows() as i64)
        };
        let width_changed = self.previous_width != 0 && self.previous_width != width;
        let height_changed = self.previous_height != 0 && self.previous_height != height;
        let previous_buffer_length = if self.previous_height > 0 {
            self.previous_viewport_top + self.previous_height
        } else {
            height
        };
        let mut prev_viewport_top = if height_changed {
            (previous_buffer_length - height).max(0)
        } else {
            self.previous_viewport_top
        };
        let mut viewport_top = prev_viewport_top;
        let mut hardware_cursor_row = self.hardware_cursor_row;

        let mut new_lines = tui.render(width as usize);
        if tui.has_overlay_entries() {
            new_lines = tui.composite_overlays(new_lines, width as usize, height as usize);
        }
        let cursor_pos = tui.extract_cursor_position(&mut new_lines, height as usize);
        let new_lines = tui.apply_line_resets(new_lines);
        self.last_new_lines = new_lines.clone();

        // First render - just output everything without clearing.
        if self.previous_lines.is_empty() && !width_changed && !height_changed {
            self.full_render(tui, &new_lines, width, height, false, cursor_pos);
            return;
        }
        // Width changes always need a full re-render because wrapping changes.
        if width_changed {
            self.full_render(tui, &new_lines, width, height, true, cursor_pos);
            return;
        }
        // Height changes need a full re-render (the Termux branch is an
        // environment-dependent tui-main-screen behavior, out of tui.ts scope).
        if height_changed {
            self.full_render(tui, &new_lines, width, height, true, cursor_pos);
            return;
        }
        if tui.get_clear_on_shrink()
            && new_lines.len() < self.max_lines_rendered
            && !tui.has_overlay_entries()
        {
            self.full_render(tui, &new_lines, width, height, true, cursor_pos);
            return;
        }

        // Find first and last changed lines.
        let mut first_changed: i64 = -1;
        let mut last_changed: i64 = -1;
        let max_lines = new_lines.len().max(self.previous_lines.len());
        for i in 0..max_lines {
            let old_line = self.previous_lines.get(i).map(String::as_str).unwrap_or("");
            let new_line = new_lines.get(i).map(String::as_str).unwrap_or("");
            if old_line != new_line {
                if first_changed == -1 {
                    first_changed = i as i64;
                }
                last_changed = i as i64;
            }
        }
        let appended_lines = new_lines.len() > self.previous_lines.len();
        if appended_lines {
            if first_changed == -1 {
                first_changed = self.previous_lines.len() as i64;
            }
            last_changed = new_lines.len() as i64 - 1;
        }
        let append_start = appended_lines
            && first_changed == self.previous_lines.len() as i64
            && first_changed > 0;

        // No changes - but still update the hardware cursor position if it moved.
        if first_changed == -1 {
            self.position_hardware_cursor(tui, cursor_pos, new_lines.len() as i64);
            self.previous_viewport_top = prev_viewport_top;
            self.previous_height = height;
            return;
        }

        // All changes are in deleted lines (nothing to render, just clear).
        if first_changed >= new_lines.len() as i64 {
            if self.previous_lines.len() > new_lines.len() {
                let mut buffer = String::from("\x1b[?2026h");
                let target_row = (new_lines.len() as i64 - 1).max(0);
                if target_row < prev_viewport_top {
                    self.full_render(tui, &new_lines, width, height, true, cursor_pos);
                    return;
                }
                let line_diff =
                    (target_row - viewport_top) - (hardware_cursor_row - prev_viewport_top);
                if line_diff > 0 {
                    buffer.push_str(&format!("\x1b[{line_diff}B"));
                } else if line_diff < 0 {
                    buffer.push_str(&format!("\x1b[{}A", -line_diff));
                }
                buffer.push('\r');
                let extra_lines = self.previous_lines.len() as i64 - new_lines.len() as i64;
                if extra_lines > height {
                    self.full_render(tui, &new_lines, width, height, true, cursor_pos);
                    return;
                }
                let clear_start_offset = i64::from(!new_lines.is_empty());
                if extra_lines > 0 && clear_start_offset > 0 {
                    buffer.push_str(&format!("\x1b[{clear_start_offset}B"));
                }
                for i in 0..extra_lines {
                    buffer.push_str("\r\x1b[2K");
                    if i < extra_lines - 1 {
                        buffer.push_str("\x1b[1B");
                    }
                }
                let move_back = (extra_lines - 1 + clear_start_offset).max(0);
                if move_back > 0 {
                    buffer.push_str(&format!("\x1b[{move_back}A"));
                }
                buffer.push_str("\x1b[?2026l");
                Self::write(tui, &buffer);
                self.cursor_row = target_row;
                self.hardware_cursor_row = target_row;
            }
            self.position_hardware_cursor(tui, cursor_pos, new_lines.len() as i64);
            self.previous_lines = new_lines;
            self.previous_width = width;
            self.previous_height = height;
            self.previous_viewport_top = prev_viewport_top;
            return;
        }

        // Differential rendering can only touch what was actually visible.
        if first_changed < prev_viewport_top {
            self.full_render(tui, &new_lines, width, height, true, cursor_pos);
            return;
        }

        // Render from the first changed line to the last.
        let mut buffer = String::from("\x1b[?2026h");
        let prev_viewport_bottom = prev_viewport_top + height - 1;
        let move_target_row = if append_start {
            first_changed - 1
        } else {
            first_changed
        };
        if move_target_row > prev_viewport_bottom {
            let current_screen_row = (hardware_cursor_row - prev_viewport_top).clamp(0, height - 1);
            let move_to_bottom = height - 1 - current_screen_row;
            if move_to_bottom > 0 {
                buffer.push_str(&format!("\x1b[{move_to_bottom}B"));
            }
            let scroll = move_target_row - prev_viewport_bottom;
            buffer.push_str(&"\r\n".repeat(scroll as usize));
            prev_viewport_top += scroll;
            viewport_top += scroll;
            hardware_cursor_row = move_target_row;
        }
        let line_diff =
            (move_target_row - viewport_top) - (hardware_cursor_row - prev_viewport_top);
        if line_diff > 0 {
            buffer.push_str(&format!("\x1b[{line_diff}B"));
        } else if line_diff < 0 {
            buffer.push_str(&format!("\x1b[{}A", -line_diff));
        }
        buffer.push_str(if append_start { "\r\n" } else { "\r" });

        let render_end = last_changed.min(new_lines.len() as i64 - 1);
        for i in first_changed..=render_end {
            if i > first_changed {
                buffer.push_str("\r\n");
            }
            let line = &new_lines[i as usize];
            if !line.starts_with("\x1b_G") && visible_width(line) > width as usize {
                // Upstream writes a crash dump, stops and throws; the buffered
                // frame is lost either way.
                panic!("Rendered line {i} exceeds terminal width");
            }
            buffer.push_str("\x1b[2K");
            buffer.push_str(line);
        }

        let mut final_cursor_row = render_end;
        if self.previous_lines.len() > new_lines.len() {
            if render_end < new_lines.len() as i64 - 1 {
                buffer.push_str(&format!(
                    "\x1b[{}B",
                    new_lines.len() as i64 - 1 - render_end
                ));
                final_cursor_row = new_lines.len() as i64 - 1;
            }
            let extra_lines = self.previous_lines.len() as i64 - new_lines.len() as i64;
            for _ in new_lines.len()..self.previous_lines.len() {
                buffer.push_str("\r\n\x1b[2K");
            }
            buffer.push_str(&format!("\x1b[{extra_lines}A"));
        }
        buffer.push_str("\x1b[?2026l");
        Self::write(tui, &buffer);

        self.cursor_row = (new_lines.len() as i64 - 1).max(0);
        self.hardware_cursor_row = final_cursor_row;
        self.max_lines_rendered = self.max_lines_rendered.max(new_lines.len());
        self.previous_viewport_top = prev_viewport_top.max(final_cursor_row - height + 1);
        self.position_hardware_cursor(tui, cursor_pos, new_lines.len() as i64);
        self.previous_lines = new_lines;
        self.previous_width = width;
        self.previous_height = height;
    }
}

impl TuiRenderer for ReferenceRenderer {
    fn do_render(&mut self, tui: &mut Tui) {
        self.do_render_impl(tui);
    }

    fn reset_render_state(&mut self, _tui: &mut Tui) {
        self.previous_lines.clear();
        self.previous_width = -1;
        self.previous_height = -1;
        self.cursor_row = 0;
        self.hardware_cursor_row = 0;
        self.max_lines_rendered = 0;
        self.previous_viewport_top = 0;
    }
}

struct SharedRenderer(Rc<RefCell<ReferenceRenderer>>);

impl TuiRenderer for SharedRenderer {
    fn do_render(&mut self, tui: &mut Tui) {
        self.0.borrow_mut().do_render(tui);
    }

    fn reset_render_state(&mut self, tui: &mut Tui) {
        self.0.borrow_mut().reset_render_state(tui);
    }
}

struct Harness {
    terminal: SharedTerminal,
    tui: Tui,
    clock: Clock,
    renderer: Rc<RefCell<ReferenceRenderer>>,
}

fn make_harness(columns: usize, rows: usize) -> Harness {
    let terminal = Rc::new(RefCell::new(TestTerminal::new(columns, rows)));
    let renderer = Rc::new(RefCell::new(ReferenceRenderer::new()));
    let clock: Clock = Rc::new(Cell::new(0.0));
    let clock_clone = clock.clone();
    let mut tui = Tui::new(
        terminal.clone(),
        Box::new(SharedRenderer(renderer.clone())),
        TuiMode::Regular,
        None,
        None,
    );
    tui.set_clock(Box::new(move || clock_clone.get()));
    Harness {
        terminal,
        tui,
        clock,
        renderer,
    }
}

/// Drain next-ticks, then fire due timers within the next `advance_ms` of
/// virtual time (mirrors `nextTick + setTimeout(20)` waits in upstream tests).
fn pump(harness: &mut Harness, advance_ms: f64) {
    let target = harness.clock.get() + advance_ms;
    loop {
        harness.tui.run_next_ticks();
        match harness.tui.next_timer_deadline() {
            Some(deadline) if deadline <= target => {
                harness.clock.set(deadline);
                harness.tui.fire_due_timer();
            }
            _ => break,
        }
    }
    harness.clock.set(target);
    harness.tui.run_next_ticks();
}

fn settle(harness: &mut Harness) {
    pump(harness, 25.0);
}

/// One upstream `terminal.sendInput` + synchronous TUI delivery.
fn send_input(harness: &mut Harness, data: &str) {
    harness.terminal.borrow_mut().send_input(data);
    harness.tui.poll_terminal_events();
}

fn render_and_flush(harness: &mut Harness) {
    harness.tui.request_render(true);
    pump(harness, 0.0);
    settle(harness);
}

fn writes_of(harness: &Harness) -> Vec<String> {
    harness.terminal.borrow().writes.clone()
}

fn writes_from(harness: &Harness, offset: usize) -> Vec<String> {
    harness.terminal.borrow().writes[offset..].to_vec()
}

fn assert_writes(actual: &[String], expected: &[&str]) {
    let actual: Vec<&str> = actual.iter().map(String::as_str).collect();
    assert_eq!(actual, expected, "terminal write sequence mismatch");
}

fn assert_oracle_json(actual: serde_json::Value, expected: &str) {
    let expected: serde_json::Value = serde_json::from_str(expected).expect("valid oracle JSON");
    assert_eq!(actual, expected, "oracle JSON mismatch");
}

/// The terminal-image capabilities cache is process-global; serialize the
/// tests in this module so capability-mutating scenarios cannot pollute the
/// byte-level write assertions of concurrent ones.
fn test_lock() -> std::sync::MutexGuard<'static, ()> {
    static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    LOCK.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
}

fn viewport_of(harness: &Harness) -> Vec<String> {
    harness
        .renderer
        .borrow()
        .last_new_lines
        .iter()
        .map(|line| strip_terminal_sequences(line).trim_end().to_string())
        .collect()
}

