/// Input pipeline: listeners consume/rewrite, debug key detection, key-release
/// filtering, and listener removal restoring pass-through.
#[test]
fn input_pipeline_listeners_debug_key_and_key_release() {
    let _tui_test_lock = test_lock();
    let mut harness = make_harness(40, 10);
    let (component, shared) = scripted_handle(&[]);
    harness.tui.add_child(component.clone());
    harness.tui.set_focus(Some(component));
    harness.tui.add_input_listener(|data| {
        if data == "consume-me" {
            return Some(TuiInputListenerResult {
                consume: true,
                data: None,
            });
        }
        if data == "rewrite" {
            return Some(TuiInputListenerResult {
                consume: false,
                data: Some("rewritten".to_string()),
            });
        }
        if data == "to-empty" {
            return Some(TuiInputListenerResult {
                consume: false,
                data: Some(String::new()),
            });
        }
        None
    });
    let second_listener = harness.tui.add_input_listener(|data| {
        if data == "drop-second" {
            return Some(TuiInputListenerResult {
                consume: true,
                data: None,
            });
        }
        None
    });
    harness.tui.start();
    settle(&mut harness);

    send_input(&mut harness, "consume-me");
    send_input(&mut harness, "rewrite");
    send_input(&mut harness, "to-empty");
    send_input(&mut harness, "drop-second");
    send_input(&mut harness, "q");
    let inputs_before_remove = shared.borrow().inputs.clone();
    {
        let mut expected =
            serde_json::from_str::<serde_json::Value>(INPUT_PIPELINE).expect("oracle JSON");
        expected
            .as_object_mut()
            .expect("object")
            .remove("inputsAfterRemove");
        assert_eq!(
            json!({
                "inputs": inputs_before_remove,
                "renderCount": harness.renderer.borrow().render_count,
            }),
            expected,
            "oracle JSON mismatch"
        );
    }

    // Removing a listener restores pass-through (upstream unsubscribe).
    harness.tui.remove_input_listener(second_listener);
    send_input(&mut harness, "drop-second");
    {
        assert_oracle_json(
            json!({
                "inputs": inputs_before_remove,
                "inputsAfterRemove": shared.borrow().inputs,
                "renderCount": harness.renderer.borrow().render_count,
            }),
            INPUT_PIPELINE,
        );
    }
    harness.tui.stop(TuiStopOptions::default());
    settle(&mut harness);

    // Debug key discovery: which sequences satisfy matchesKey("shift+ctrl+d")?
    let candidates = ["\u{4}", "\x1b[100;6u", "\x1b[100;4u", "\x1b[100;5u"];
    let mut hits = Vec::new();
    for candidate in candidates {
        let mut debug_harness = make_harness(40, 10);
        let hits_cell = std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0));
        let hits_clone = hits_cell.clone();
        debug_harness.tui.on_debug = Some(Box::new(move || {
            hits_clone.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        }));
        debug_harness.tui.start();
        send_input(&mut debug_harness, candidate);
        debug_harness.tui.run_next_ticks();
        hits.push(hits_cell.load(std::sync::atomic::Ordering::SeqCst));
        debug_harness.tui.stop(TuiStopOptions::default());
        settle(&mut debug_harness);
    }
    assert_oracle_json(json!({ "candidates": candidates, "hits": hits }), DEBUG_KEY);

    // Key release filtering.
    let mut release_harness = make_harness(40, 10);
    let (component, shared) = scripted_handle(&[]);
    release_harness.tui.add_child(component.clone());
    release_harness.tui.set_focus(Some(component));
    release_harness.tui.start();
    settle(&mut release_harness);
    send_input(&mut release_harness, "\x1b[100;1:3u");
    send_input(&mut release_harness, "x");
    {
        let component_ref = shared.borrow();
        assert_oracle_json(json!({ "inputs": component_ref.inputs }), KEY_RELEASE);
    }
    release_harness.tui.stop(TuiStopOptions::default());
    settle(&mut release_harness);
}

