/// tui-render.test.ts "TUI resize handling" (non-Termux behavior).
#[test]
fn resize_triggers_full_re_renders() {
    let _tui_test_lock = test_lock();
    let mut harness = make_harness(40, 10);
    let (component, shared) = static_handle(&[]);
    harness.tui.add_child(component);
    harness.tui.start();
    settle(&mut harness);
    shared.borrow_mut().lines = vec!["Line 0".into(), "Line 1".into(), "Line 2".into()];
    harness.tui.request_render(false);
    settle(&mut harness);
    let redraws_before = harness.tui.full_redraws();

    harness.terminal.borrow_mut().writes.clear();
    harness.terminal.borrow_mut().resize(60, 10);
    harness.tui.poll_terminal_events();
    settle(&mut harness);
    let width_delta = harness.tui.full_redraws() - redraws_before;
    assert_writes(&writes_of(&harness), RESIZE_WIDTH_WRITES);

    harness.terminal.borrow_mut().writes.clear();
    harness.terminal.borrow_mut().resize(60, 15);
    harness.tui.poll_terminal_events();
    settle(&mut harness);
    let height_delta = harness.tui.full_redraws() - redraws_before - width_delta;
    assert_writes(&writes_of(&harness), RESIZE_HEIGHT_WRITES);
    assert_oracle_json(
        json!({ "width": width_delta, "height": height_delta }),
        RESIZE_DELTAS,
    );
    assert!(viewport_of(&harness)
        .first()
        .is_some_and(|line| line.contains("Line 0")));
    harness.tui.stop(TuiStopOptions::default());
    settle(&mut harness);
}

