/// tui-overlay-style-leak.test.ts: compositing resets SGR/OSC8 at edges.
#[test]
fn overlay_compositing_resets_styles() {
    let _tui_test_lock = test_lock();
    let width = 20usize;
    let base_line = format!("\x1b[3m{}\x1b[23m", "X".repeat(width));

    // No overlay: a trailing reset beyond the last visible column must not
    // leak onto the next line.
    let mut harness = make_harness(width, 6);
    let (base, shared) = static_handle(&[]);
    harness.tui.add_child(base);
    shared.borrow_mut().lines = vec![base_line.clone(), "INPUT".to_string()];
    harness.tui.start();
    render_and_flush(&mut harness);
    let no_overlay_lines: Vec<String> = harness.renderer.borrow().last_new_lines.clone();
    harness.tui.stop(TuiStopOptions::default());
    settle(&mut harness);
    assert_writes(&no_overlay_lines, STYLE_LEAK_NO_OVERLAY_LINES);

    // Overlay slicing that drops trailing SGR resets.
    let mut harness = make_harness(width, 6);
    let (base, shared) = static_handle(&[]);
    harness.tui.add_child(base);
    shared.borrow_mut().lines = vec![base_line.clone(), "INPUT".to_string()];
    harness.tui.show_overlay(
        ComponentHandle::new(StaticLines {
            lines: vec!["OVR".into()],
            inputs: Vec::new(),
        }),
        Some(OverlayOptions {
            row: Some(SizeValue::Number(0.0)),
            col: Some(SizeValue::Number(5.0)),
            width: Some(SizeValue::Number(3.0)),
            ..Default::default()
        }),
    );
    harness.tui.start();
    render_and_flush(&mut harness);
    let overlay_lines: Vec<String> = harness.renderer.borrow().last_new_lines.clone();
    assert_writes(&overlay_lines, STYLE_LEAK_OVERLAY_LINES);
    harness.tui.stop(TuiStopOptions::default());
    settle(&mut harness);
}

/// compositeTuiLine pure-function oracle table.
#[test]
fn composite_tui_line_matches_oracle_table() {
    let _tui_test_lock = test_lock();
    let table: Vec<(&str, &str, usize, usize, usize)> = vec![
        ("base", "ovr", 0, 3, 10),
        ("\x1b[3mbase\x1b[23m", "ovr", 2, 3, 10),
        ("left-overside", "OVR", 5, 3, 14),
        ("XXXXXXXXXX", "YYYYYYYYYY", 3, 10, 10),
        ("\x1b[3mXXXXXXXXXX\x1b[23m", "\x1b[1mYY\x1b[22m", 3, 4, 10),
        ("日本語のテキスト", "英語", 2, 4, 16),
        (
            "hyper\x1b]8;;http://x\x07link\x1b]8;;\x07tail",
            "ov",
            5,
            4,
            24,
        ),
        ("", "only", 0, 4, 8),
        ("base", "", 2, 3, 10),
    ];
    let results: Vec<String> = table
        .iter()
        .map(|(base, overlay, col, width, total)| {
            composite_tui_line(base, overlay, *col, *width, *total)
        })
        .collect();
    let actual: Vec<&str> = results.iter().map(String::as_str).collect();
    assert_eq!(actual, COMPOSITE_TABLE);
}

/// CURSOR_MARKER extraction and hardware cursor positioning.
#[test]
fn cursor_marker_extraction_and_positioning() {
    let _tui_test_lock = test_lock();
    let mut harness = make_harness(40, 10);
    let (component, shared) = static_handle(&[]);
    harness.tui.add_child(component.clone());
    harness.tui.set_focus(Some(component));
    harness.tui.set_show_hardware_cursor(true);
    shared.borrow_mut().lines = vec![format!("alpha{CURSOR_MARKER}"), "beta".to_string()];
    harness.tui.start();
    settle(&mut harness);
    assert_writes(&writes_of(&harness), CURSOR_MARKER_WRITES);
    assert_oracle_json(json!(viewport_of(&harness)), CURSOR_MARKER_VIEWPORT);

    harness.terminal.borrow_mut().writes.clear();
    shared.borrow_mut().lines = vec!["alpha".to_string(), format!("beta{CURSOR_MARKER}")];
    harness.tui.request_render(false);
    settle(&mut harness);
    assert_writes(&writes_of(&harness), CURSOR_MARKER_MOVED_WRITES);

    harness.terminal.borrow_mut().writes.clear();
    harness.tui.set_show_hardware_cursor(false);
    settle(&mut harness);
    assert_writes(&writes_of(&harness), CURSOR_MARKER_DISABLED_WRITES);
    harness.tui.stop(TuiStopOptions::default());
    settle(&mut harness);
}

/// dispatchMouseToOverlay hit-testing against last rendered overlay bounds.
#[test]
fn dispatch_mouse_to_overlay_hits_and_retargets() {
    let _tui_test_lock = test_lock();
    let mut harness = make_harness(40, 10);
    harness.tui.add_child(ComponentHandle::new(EmptyContent));
    let (overlay, shared) = scripted_handle(&["BTN"]);
    harness.tui.show_overlay(
        overlay.clone(),
        Some(OverlayOptions {
            row: Some(SizeValue::Number(1.0)),
            col: Some(SizeValue::Number(2.0)),
            width: Some(SizeValue::Number(10.0)),
            non_capturing: true,
            ..Default::default()
        }),
    );
    harness.tui.start();
    render_and_flush(&mut harness);

    let mouse_seen: Rc<RefCell<Option<serde_json::Value>>> = Rc::new(RefCell::new(None));
    {
        let mouse_seen = mouse_seen.clone();
        shared.borrow_mut().mouse_handler = Some(Box::new(move |event: &TuiMouseEvent| {
            *mouse_seen.borrow_mut() = Some(json!({
                "x": event.x,
                "y": event.y,
                "screenX": event.screen_x,
                "screenY": event.screen_y,
                "width": event.width,
                "height": event.height,
            }));
            TuiMouseEventResult {
                handled: true,
                ..Default::default()
            }
        }));
    }
    let dispatch = harness.tui.dispatch_mouse_to_overlay(&TuiMouseEvent {
        event_type: TuiMouseEventType::Press,
        button: TuiMouseButton::Left,
        x: 4,
        y: 1,
        screen_x: 4,
        screen_y: 1,
        width: 40,
        height: 10,
        shift: false,
        alt: false,
        ctrl: false,
        wheel_delta: None,
        click_count: None,
    });
    assert_oracle_json(
        json!({
            "seen": mouse_seen.borrow().clone().expect("mouse handler invoked"),
            "resultHit": dispatch.hit,
            "handled": dispatch.result.map(|r| r.result.handled),
        }),
        MOUSE_OVERLAY_HIT,
    );
    harness.tui.stop(TuiStopOptions::default());
    settle(&mut harness);
}

// -------------------------------------------------------- focus machine tests

type SharedOverlay = Rc<RefCell<ScriptedOverlay>>;

struct FocusFixture {
    harness: Harness,
    components: HashMap<&'static str, ComponentHandle>,
    overlays: HashMap<&'static str, OverlayHandle>,
    shared: HashMap<&'static str, SharedOverlay>,
    editor: Option<SharedOverlay>,
}

impl FocusFixture {
    /// Upstream harness: `addChild(EmptyContent); setFocus(editor); start()`.
    fn with_editor() -> FocusFixture {
        let mut fixture = FocusFixture::plain();
        let (editor_handle, editor_shared) = scripted_handle(&["EDITOR"]);
        fixture.components.insert("editor", editor_handle.clone());
        fixture.shared.insert("editor", editor_shared.clone());
        fixture.editor = Some(editor_shared);
        fixture.harness.tui.set_focus(Some(editor_handle));
        fixture
    }

    /// Upstream harness without an editor focus target.
    fn plain() -> FocusFixture {
        let mut harness = make_harness(80, 24);
        harness.tui.add_child(ComponentHandle::new(EmptyContent));
        FocusFixture {
            harness,
            components: HashMap::new(),
            overlays: HashMap::new(),
            shared: HashMap::new(),
            editor: None,
        }
    }

    /// Upstream harness start (`setFocus` happens in the constructors).
    fn start(&mut self) {
        self.harness.tui.start();
    }

    fn register(&mut self, name: &'static str, handle: ComponentHandle, shared: SharedOverlay) {
        self.components.insert(name, handle);
        self.shared.insert(name, shared);
    }

    /// Show a fresh scripted overlay under `name` with `options`.
    fn show(&mut self, name: &'static str, options: Option<OverlayOptions>) -> OverlayHandle {
        let (handle, shared) = scripted_handle(&[name]);
        self.register(name, handle.clone(), shared);
        let overlay_handle = self.harness.tui.show_overlay(handle, options);
        self.overlays.insert(name, overlay_handle);
        overlay_handle
    }

    /// Show an already-registered component as an overlay.
    fn show_registered(
        &mut self,
        name: &'static str,
        options: Option<OverlayOptions>,
    ) -> OverlayHandle {
        let handle = self.components[name].clone();
        let overlay_handle = self.harness.tui.show_overlay(handle, options);
        self.overlays.insert(name, overlay_handle);
        overlay_handle
    }

    /// Show a scripted overlay with a custom input script.
    fn show_scripted(
        &mut self,
        name: &'static str,
        options: Option<OverlayOptions>,
        script: ScriptFn,
    ) -> OverlayHandle {
        let overlay_handle = self.show(name, options);
        self.shared[name].borrow_mut().script = Some(script);
        overlay_handle
    }

    /// Register a plain (non-overlay) scripted component.
    fn plain_component(&mut self, name: &'static str) {
        let (handle, shared) = scripted_handle(&[name]);
        self.register(name, handle, shared);
    }

    fn component(&self, name: &str) -> ComponentHandle {
        self.components[name].clone()
    }

    fn inputs_of(&self, name: &str) -> Vec<String> {
        self.shared[name].borrow().inputs.clone()
    }

    fn focused_of(&self, name: &str) -> bool {
        self.components[name].with_mut(|c| c.focused())
    }

    fn focus_script(replacement: &'static str) -> ScriptFn {
        Box::new(move |data| {
            if data == "b" {
                vec![ScriptAction::Focus(replacement)]
            } else {
                Vec::new()
            }
        })
    }

    /// One upstream `terminal.sendInput` + scripted action application.
    fn send(&mut self, data: &'static str, scripted: &'static str) {
        self.harness.terminal.borrow_mut().send_input(data);
        self.harness.tui.poll_terminal_events();
        let actions = self.shared[scripted].borrow_mut().take_pending_actions();
        for action in actions {
            self.apply_action(action);
        }
    }

    fn apply_action(&mut self, action: ScriptAction) {
        match action {
            ScriptAction::Focus(name) => {
                let target = self.component(name);
                self.harness.tui.set_focus(Some(target));
            }
            ScriptAction::FocusNull => self.harness.tui.set_focus(None),
            ScriptAction::Unfocus { overlay, target } => {
                let options = target.map(|target| OverlayUnfocusOptions { target });
                self.harness.tui.overlay_unfocus(&overlay, options);
            }
            ScriptAction::RebuildBaseAndFocus { base, child } => {
                base.borrow_mut().clear();
                base.borrow_mut().add_child(child.clone());
                self.harness.tui.set_focus(Some(child));
            }
        }
    }

    fn stop(&mut self) {
        self.harness.tui.stop(TuiStopOptions::default());
        settle(&mut self.harness);
    }
}

/// overlay-non-capturing.test.ts "focus management" core scenarios.
#[test]
fn focus_management_core_scenarios() {
    let _tui_test_lock = test_lock();
    // non-capturing overlay preserves focus on creation
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editor": fx.focused_of("editor"),
                "overlay": fx.harness.tui.overlay_is_focused(&overlay_handle),
            }),
            FOCUS_NC_PRESERVES_FOCUS,
        );
        fx.stop();
    }
    // focus() transfers focus to the overlay
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_focus(&overlay_handle);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editor": fx.focused_of("editor"),
                "overlay": fx.focused_of("OVERLAY"),
                "handleFocused": fx.harness.tui.overlay_is_focused(&overlay_handle),
            }),
            FOCUS_FOCUS_TRANSFERS,
        );
        fx.stop();
    }
    // unfocus() restores previous focus
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_focus(&overlay_handle);
        fx.harness.tui.overlay_unfocus(&overlay_handle, None);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editor": fx.focused_of("editor"),
                "overlay": fx.focused_of("OVERLAY"),
                "handleFocused": fx.harness.tui.overlay_is_focused(&overlay_handle),
            }),
            FOCUS_UNFOCUS_RESTORES,
        );
        fx.stop();
    }
    // setHidden(false) on non-capturing overlay does not auto-focus
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_set_hidden(&overlay_handle, true);
        fx.harness.tui.overlay_set_hidden(&overlay_handle, false);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editor": fx.focused_of("editor"),
                "overlay": fx.focused_of("OVERLAY"),
            }),
            FOCUS_SET_HIDDEN_FALSE_NO_AUTOFOCUS,
        );
        fx.stop();
    }
    // hide() when overlay is not focused does not change focus
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_hide(&overlay_handle);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({ "editor": fx.focused_of("editor") }),
            FOCUS_HIDE_NOT_FOCUSED,
        );
        fx.stop();
    }
    // hide() when focused restores focus correctly
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_focus(&overlay_handle);
        fx.harness.tui.overlay_hide(&overlay_handle);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editor": fx.focused_of("editor"),
                "overlay": fx.focused_of("OVERLAY"),
            }),
            FOCUS_HIDE_FOCUSED_RESTORES,
        );
        fx.stop();
    }
    // capturing overlay removed with non-capturing below restores focus
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        fx.show(
            "NC",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        let capturing = fx.show("CAP", None);
        let focused_on_show = fx.harness.tui.overlay_is_focused(&capturing);
        fx.harness.tui.overlay_hide(&capturing);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "focusedOnShow": focused_on_show,
                "editor": fx.focused_of("editor"),
                "nonCapturing": fx.focused_of("NC"),
            }),
            FOCUS_CAPTURING_REMOVED_NC_BELOW,
        );
        fx.stop();
    }
}

/// overlay-non-capturing.test.ts: sub-overlay cleanup + removed child.
#[test]
fn focus_management_sub_overlay_scenarios() {
    let _tui_test_lock = test_lock();
    // sub-overlay cleanup then hideOverlay restores focus and input to editor
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let timer_handle = fx.show(
            "TIMER",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.show("CTRL", None);
        let controller_focused = fx.harness.tui.overlay_is_focused(&fx.overlays["CTRL"]);
        let editor_focused_after_show = fx.focused_of("editor");
        fx.harness.tui.overlay_hide(&timer_handle);
        fx.harness.tui.hide_overlay();
        render_and_flush(&mut fx.harness);
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "controllerFocused": controller_focused,
                "editorFocusedAfterShow": editor_focused_after_show,
                "editor": fx.focused_of("editor"),
                "controller": fx.focused_of("CTRL"),
                "timer": fx.focused_of("TIMER"),
                "editorInputs": fx.inputs_of("editor"),
                "controllerInputs": fx.inputs_of("CTRL"),
                "timerInputs": fx.inputs_of("TIMER"),
            }),
            FOCUS_SUB_OVERLAY_CLEANUP,
        );
        fx.stop();
    }
    // removed focused child overlay does not become parent overlay fallback
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let child_handle = fx.show(
            "CHILD",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_focus(&child_handle);
        let parent_handle = fx.show("PARENT", None);
        let parent_focused = fx.harness.tui.overlay_is_focused(&parent_handle);
        fx.harness.tui.overlay_hide(&child_handle);
        fx.harness.tui.overlay_hide(&parent_handle);
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "parentFocused": parent_focused,
                "editorInputs": fx.inputs_of("editor"),
                "childInputs": fx.inputs_of("CHILD"),
                "parentInputs": fx.inputs_of("PARENT"),
                "editor": fx.focused_of("editor"),
            }),
            FOCUS_REMOVED_CHILD_NO_FALLBACK,
        );
        fx.stop();
    }
}

/// overlay-non-capturing.test.ts: invisible overlay input redirection.
#[test]
fn invisible_focused_overlay_redirects_input() {
    let _tui_test_lock = test_lock();
    let mut fx = FocusFixture::with_editor();
    fx.start();
    fx.show("FALLBACK", None);
    fx.show(
        "NC",
        Some(OverlayOptions {
            non_capturing: true,
            ..Default::default()
        }),
    );
    let visible_flag = Rc::new(Cell::new(true));
    {
        let visible_flag = visible_flag.clone();
        fx.show(
            "PRIMARY",
            Some(OverlayOptions {
                visible: Some(Box::new(move |_, _| visible_flag.get())),
                ..Default::default()
            }),
        );
    }
    let primary_focused = fx.focused_of("PRIMARY");
    visible_flag.set(false);
    fx.send("x", "editor");
    render_and_flush(&mut fx.harness);
    assert_oracle_json(
        json!({
            "primaryFocused": primary_focused,
            "primaryInputs": fx.inputs_of("PRIMARY"),
            "nonCapturingInputs": fx.inputs_of("NC"),
            "fallbackInputs": fx.inputs_of("FALLBACK"),
            "fallbackFocused": fx.focused_of("FALLBACK"),
        }),
        FOCUS_INVISIBLE_REDIRECT,
    );
    fx.stop();
}

/// overlay-non-capturing.test.ts: base focus replacement scenarios with
/// scripted handleInput callbacks.
#[test]
fn base_focus_replacement_scenarios() {
    let _tui_test_lock = test_lock();
    // active base focus replacement receives close input before overlay restore
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        fx.show_scripted("OVERLAY", None, FocusFixture::focus_script("REPLACEMENT"));
        fx.plain_component("REPLACEMENT");
        fx.shared["REPLACEMENT"].borrow_mut().script = Some(Box::new(|data| {
            if data == "\r" {
                vec![ScriptAction::Focus("editor")]
            } else {
                Vec::new()
            }
        }));
        let overlay_focused = fx.harness.tui.overlay_is_focused(&fx.overlays["OVERLAY"]);
        fx.send("b", "OVERLAY");
        render_and_flush(&mut fx.harness);
        let replacement_focused = fx.focused_of("REPLACEMENT");
        fx.send("\r", "REPLACEMENT");
        render_and_flush(&mut fx.harness);
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "overlayFocused": overlay_focused,
                "replacementFocused": replacement_focused,
                "replacementInputs": fx.inputs_of("REPLACEMENT"),
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "overlayFocusedEnd": fx.harness.tui.overlay_is_focused(&fx.overlays["OVERLAY"]),
            }),
            FOCUS_BASE_REPLACEMENT_CLOSE_INPUT,
        );
        fx.stop();
    }
    // active replacement still receives input when it is another overlay preFocus
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        fx.harness.tui.set_focus(Some(fx.component("editor")));
        fx.show(
            "PASSIVE",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.set_focus(Some(fx.component("editor")));
        fx.show_scripted("OVERLAY", None, FocusFixture::focus_script("REPLACEMENT"));
        fx.plain_component("REPLACEMENT");
        fx.shared["REPLACEMENT"].borrow_mut().script = Some(Box::new(|data| {
            if data == "\r" {
                vec![ScriptAction::Focus("editor")]
            } else {
                Vec::new()
            }
        }));
        fx.send("b", "OVERLAY");
        render_and_flush(&mut fx.harness);
        let replacement_focused = fx.focused_of("REPLACEMENT");
        fx.send("1", "REPLACEMENT");
        fx.send("\r", "REPLACEMENT");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "replacementFocused": replacement_focused,
                "replacementInputs": fx.inputs_of("REPLACEMENT"),
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "overlayFocusedEnd": fx.harness.tui.overlay_is_focused(&fx.overlays["OVERLAY"]),
            }),
            FOCUS_REPLACEMENT_IS_PRE_FOCUS,
        );
        fx.stop();
    }
}

/// overlay-non-capturing.test.ts: blocked replacement state machine.
#[test]
fn blocked_replacement_state_machine() {
    let _tui_test_lock = test_lock();
    // blocked replacement can move focus internally before overlay restore
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let (base_handle, base_shared) = ComponentHandle::with_shared(Container::new());
        fx.harness.tui.add_child(base_handle);
        for (name, lines) in [
            ("editor", vec!["EDITOR"]),
            ("FIRST", vec!["FIRST"]),
            ("SECOND", vec!["SECOND"]),
        ] {
            let (handle, shared) = scripted_handle(&lines);
            fx.register(name, handle.clone(), shared);
            base_shared.borrow_mut().add_child(handle);
        }
        fx.harness.tui.set_focus(Some(fx.component("editor")));
        fx.show_scripted("OVERLAY", None, FocusFixture::focus_script("FIRST"));
        fx.shared["FIRST"].borrow_mut().script = Some(Box::new(|data| {
            if data == "n" {
                vec![ScriptAction::Focus("SECOND")]
            } else {
                Vec::new()
            }
        }));
        {
            let base_shared = base_shared.clone();
            let editor_handle = fx.component("editor");
            fx.shared["SECOND"].borrow_mut().script = Some(Box::new(move |data| {
                if data == "\r" {
                    vec![ScriptAction::RebuildBaseAndFocus {
                        base: base_shared.clone(),
                        child: editor_handle.clone(),
                    }]
                } else {
                    Vec::new()
                }
            }));
        }
        fx.send("b", "OVERLAY");
        render_and_flush(&mut fx.harness);
        fx.send("n", "FIRST");
        render_and_flush(&mut fx.harness);
        fx.send("2", "SECOND");
        fx.send("\r", "SECOND");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "firstInputs": fx.inputs_of("FIRST"),
                "secondInputs": fx.inputs_of("SECOND"),
                "overlayFocused": fx.harness.tui.overlay_is_focused(&fx.overlays["OVERLAY"]),
            }),
            FOCUS_BLOCKED_INTERNAL_MOVES,
        );
        fx.stop();
    }
    // removed replacement restores overlay even when overlay preFocus differs
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let (base_handle, base_shared) = ComponentHandle::with_shared(Container::new());
        fx.harness.tui.add_child(base_handle);
        for name in ["PALETTE", "REPLACEMENT"] {
            let (handle, shared) = scripted_handle(&[name]);
            fx.register(name, handle.clone(), shared);
            base_shared.borrow_mut().add_child(handle);
        }
        fx.harness.tui.set_focus(Some(fx.component("PALETTE")));
        fx.show_scripted("OVERLAY", None, FocusFixture::focus_script("REPLACEMENT"));
        {
            let base_shared = base_shared.clone();
            let editor_handle = fx.component("editor");
            fx.shared["REPLACEMENT"].borrow_mut().script = Some(Box::new(move |data| {
                if data == "\r" {
                    vec![ScriptAction::RebuildBaseAndFocus {
                        base: base_shared.clone(),
                        child: editor_handle.clone(),
                    }]
                } else {
                    Vec::new()
                }
            }));
        }
        fx.send("b", "OVERLAY");
        render_and_flush(&mut fx.harness);
        fx.send("\r", "REPLACEMENT");
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "replacementInputs": fx.inputs_of("REPLACEMENT"),
                "editorInputs": fx.inputs_of("editor"),
                "overlayFocused": fx.harness.tui.overlay_is_focused(&fx.overlays["OVERLAY"]),
            }),
            FOCUS_REMOVED_REPLACEMENT_RESTORES,
        );
        fx.stop();
    }
    // unfocus target releases a blocked overlay while replacement remains focused
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        fx.plain_component("FALLBACK");
        fx.plain_component("TARGET");
        fx.plain_component("REPLACEMENT");
        fx.shared["REPLACEMENT"].borrow_mut().script = Some(Box::new(|data| {
            if data == "\r" {
                vec![ScriptAction::Focus("FALLBACK")]
            } else {
                Vec::new()
            }
        }));
        let overlay_handle = fx.show("OVERLAY", None);
        let target_handle = fx.component("TARGET");
        fx.shared["OVERLAY"].borrow_mut().script = Some(Box::new(move |data| {
            if data == "b" {
                vec![
                    ScriptAction::Focus("REPLACEMENT"),
                    ScriptAction::Unfocus {
                        overlay: overlay_handle,
                        target: Some(Some(target_handle.clone())),
                    },
                ]
            } else {
                Vec::new()
            }
        }));
        fx.send("b", "OVERLAY");
        render_and_flush(&mut fx.harness);
        let replacement_focused = fx.focused_of("REPLACEMENT");
        fx.send("\r", "REPLACEMENT");
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "replacementFocused": replacement_focused,
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "replacementInputs": fx.inputs_of("REPLACEMENT"),
                "fallbackInputs": fx.inputs_of("FALLBACK"),
                "targetInputs": fx.inputs_of("TARGET"),
            }),
            FOCUS_UNFOCUS_TARGET_RELEASES_BLOCKED,
        );
        fx.stop();
    }
}

/// overlay-non-capturing.test.ts: focus restore after base focus steal.
#[test]
fn focus_restore_after_steal_scenarios() {
    let _tui_test_lock = test_lock();
    // handleInput restores focus to a visible focused overlay after base steal
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        fx.show("OVERLAY", None);
        fx.plain_component("REPLACEMENT");
        let overlay_focused = fx.focused_of("OVERLAY");
        fx.harness.tui.set_focus(Some(fx.component("REPLACEMENT")));
        fx.harness.tui.set_focus(Some(fx.component("editor")));
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "overlayFocused": overlay_focused,
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "editorInputs": fx.inputs_of("editor"),
                "overlayFocusedEnd": fx.focused_of("OVERLAY"),
            }),
            FOCUS_RESTORE_AFTER_STEAL,
        );
        fx.stop();
    }
    // handleInput restores focus to explicitly focused raw sub-overlay
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        fx.show("CONTROLLER", None);
        let sub_handle = fx.show(
            "SUB",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_focus(&sub_handle);
        fx.harness.tui.set_focus(Some(fx.component("editor")));
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "subInputs": fx.inputs_of("SUB"),
                "controllerInputs": fx.inputs_of("CONTROLLER"),
                "editorInputs": fx.inputs_of("editor"),
            }),
            FOCUS_RAW_SUB_OVERLAY_RESTORE,
        );
        fx.stop();
    }
    // passive non-capturing overlay does not regain input after base focus
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        fx.show(
            "PASSIVE",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editorInputs": fx.inputs_of("editor"),
                "passiveInputs": fx.inputs_of("PASSIVE"),
                "editor": fx.focused_of("editor"),
            }),
            FOCUS_PASSIVE_NO_REGAIN,
        );
        fx.stop();
    }
    // explicitly focused non-capturing overlay regains input after base steal
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "NC",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_focus(&overlay_handle);
        fx.harness.tui.set_focus(Some(fx.component("editor")));
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "overlayInputs": fx.inputs_of("NC"),
                "editorInputs": fx.inputs_of("editor"),
            }),
            FOCUS_EXPLICIT_NC_REGAINS,
        );
        fx.stop();
    }
    // unfocus() prevents a visible overlay from regaining input
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show("OVERLAY", None);
        fx.harness.tui.overlay_unfocus(&overlay_handle, None);
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editorInputs": fx.inputs_of("editor"),
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "editor": fx.focused_of("editor"),
            }),
            FOCUS_UNFOCUS_PREVENTS_REGAIN,
        );
        fx.stop();
    }
    // setFocus(null) explicitly clears the visible overlay restore
    {
        let mut fx = FocusFixture::plain();
        fx.start();
        fx.show("OVERLAY", None);
        fx.harness.tui.set_focus(None);
        fx.send("x", "OVERLAY");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "overlay": fx.focused_of("OVERLAY"),
            }),
            FOCUS_SET_FOCUS_NULL_CLEARS,
        );
        fx.stop();
    }
    // blocked replacement setFocus(null) resumes the visible overlay
    {
        let mut fx = FocusFixture::plain();
        fx.start();
        fx.plain_component("REPLACEMENT");
        fx.shared["REPLACEMENT"].borrow_mut().script = Some(Box::new(|data| {
            if data == "\r" {
                vec![ScriptAction::FocusNull]
            } else {
                Vec::new()
            }
        }));
        fx.show_scripted("OVERLAY", None, FocusFixture::focus_script("REPLACEMENT"));
        fx.send("b", "OVERLAY");
        render_and_flush(&mut fx.harness);
        fx.send("\r", "REPLACEMENT");
        fx.send("x", "OVERLAY");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "replacementInputs": fx.inputs_of("REPLACEMENT"),
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "overlay": fx.focused_of("OVERLAY"),
            }),
            FOCUS_BLOCKED_SET_FOCUS_NULL,
        );
        fx.stop();
    }
}

/// overlay-non-capturing.test.ts: visibility/eligibility restore scenarios.
#[test]
fn focus_visibility_eligibility_scenarios() {
    let _tui_test_lock = test_lock();
    // temporarily invisible focused overlay falls back without losing
    // restore eligibility
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let visible_flag = Rc::new(Cell::new(true));
        {
            let visible_flag = visible_flag.clone();
            fx.show(
                "OVERLAY",
                Some(OverlayOptions {
                    visible: Some(Box::new(move |_, _| visible_flag.get())),
                    ..Default::default()
                }),
            );
        }
        fx.harness.tui.set_focus(Some(fx.component("editor")));
        visible_flag.set(false);
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        let after_x = (fx.inputs_of("editor"), fx.inputs_of("OVERLAY"));
        visible_flag.set(true);
        fx.send("y", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editorInputs": after_x.0,
                "overlayInputs": after_x.1,
                "editorInputsEnd": fx.inputs_of("editor"),
                "overlayInputsEnd": fx.inputs_of("OVERLAY"),
            }),
            FOCUS_INVISIBLE_KEEPS_ELIGIBILITY,
        );
        fx.stop();
    }
    // temporarily invisible focused overlay with null preFocus restores when
    // visible again
    {
        let mut fx = FocusFixture::plain();
        fx.start();
        let visible_flag = Rc::new(Cell::new(true));
        {
            let visible_flag = visible_flag.clone();
            fx.show(
                "OVERLAY",
                Some(OverlayOptions {
                    visible: Some(Box::new(move |_, _| visible_flag.get())),
                    ..Default::default()
                }),
            );
        }
        visible_flag.set(false);
        fx.send("x", "OVERLAY");
        render_and_flush(&mut fx.harness);
        let after_x = fx.inputs_of("OVERLAY");
        visible_flag.set(true);
        fx.send("y", "OVERLAY");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "afterX": after_x,
                "overlayInputs": fx.inputs_of("OVERLAY"),
            }),
            FOCUS_INVISIBLE_NULL_PRE_FOCUS,
        );
        fx.stop();
    }
    // cyclic overlay preFocus ancestry does not hang focus changes
    {
        let mut fx = FocusFixture::with_editor();
        let (overlay_component, overlay_shared) = scripted_handle(&["OVERLAY"]);
        fx.register("OVERLAY", overlay_component.clone(), overlay_shared);
        // Upstream: setFocus(overlay) happens BEFORE start().
        fx.harness.tui.set_focus(Some(overlay_component.clone()));
        fx.harness.tui.start();
        let overlay_handle = fx.show_registered(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_focus(&overlay_handle);
        fx.harness.tui.set_focus(Some(fx.component("editor")));
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editorInputs": fx.inputs_of("editor"),
                "overlayInputs": fx.inputs_of("OVERLAY"),
            }),
            FOCUS_CYCLIC_PRE_FOCUS,
        );
        fx.stop();
    }
    // handleInput restores the focus-order top overlay after base focus steal
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let lower_handle = fx.show("LOWER", None);
        fx.show("UPPER", None);
        fx.harness.tui.overlay_focus(&lower_handle);
        fx.harness.tui.set_focus(Some(fx.component("editor")));
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "lowerInputs": fx.inputs_of("LOWER"),
                "upperInputs": fx.inputs_of("UPPER"),
                "editorInputs": fx.inputs_of("editor"),
            }),
            FOCUS_FOCUS_ORDER_TOP,
        );
        fx.stop();
    }
    // hideOverlay() does not reassign focus when topmost overlay is
    // non-capturing
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        fx.show("CAP", None);
        fx.show(
            "NC",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        let capturing_focused = fx.focused_of("CAP");
        fx.harness.tui.hide_overlay();
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "capturingFocused": capturing_focused,
                "capturingFocusedEnd": fx.focused_of("CAP"),
            }),
            FOCUS_HIDE_OVERLAY_NC_TOP,
        );
        fx.stop();
    }
    // multiple capturing and non-capturing overlays restore through removals
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let c1_handle = fx.show("C1", None);
        fx.show(
            "N1",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        let c2_handle = fx.show("C2", None);
        fx.show(
            "N2",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        let c2_focused = fx.focused_of("C2");
        fx.harness.tui.overlay_hide(&c2_handle);
        render_and_flush(&mut fx.harness);
        let c1_focused = fx.focused_of("C1");
        fx.harness.tui.overlay_hide(&c1_handle);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "c2Focused": c2_focused,
                "c1Focused": c1_focused,
                "editorFocused": fx.focused_of("editor"),
            }),
            FOCUS_MIXED_REMOVALS,
        );
        fx.stop();
    }
    // capturing overlay unfocus() on topmost capturing overlay falls back
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show("CAP", None);
        let capturing_focused = fx.focused_of("CAP");
        fx.harness.tui.overlay_unfocus(&overlay_handle, None);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "capturingFocused": capturing_focused,
                "editorFocused": fx.focused_of("editor"),
                "capturingFocusedEnd": fx.focused_of("CAP"),
            }),
            FOCUS_UNFOCUS_TOPMOST_FALLS_BACK,
        );
        fx.stop();
    }
}

/// overlay-non-capturing.test.ts "no-op guards".
#[test]
fn overlay_no_op_guards() {
    let _tui_test_lock = test_lock();
    // focus() on hidden overlay is a no-op
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_set_hidden(&overlay_handle, true);
        fx.harness.tui.overlay_focus(&overlay_handle);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editor": fx.focused_of("editor"),
                "handleFocused": fx.harness.tui.overlay_is_focused(&overlay_handle),
            }),
            FOCUS_FOCUS_HIDDEN_NOOP,
        );
        fx.stop();
    }
    // focus() after hide() is a no-op
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_hide(&overlay_handle);
        fx.harness.tui.overlay_focus(&overlay_handle);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editor": fx.focused_of("editor"),
                "handleFocused": fx.harness.tui.overlay_is_focused(&overlay_handle),
            }),
            FOCUS_FOCUS_AFTER_HIDE_NOOP,
        );
        fx.stop();
    }
    // unfocus() when overlay does not have focus is a no-op
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let overlay_handle = fx.show(
            "OVERLAY",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_unfocus(&overlay_handle, None);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editor": fx.focused_of("editor"),
                "overlay": fx.focused_of("OVERLAY"),
            }),
            FOCUS_UNFOCUS_NOT_FOCUSED_NOOP,
        );
        fx.stop();
    }
    // unfocus() with null preFocus clears focus and does not route input back
    {
        let mut fx = FocusFixture::plain();
        fx.start();
        let overlay_handle = fx.show("OVERLAY", None);
        let overlay_focused = fx.focused_of("OVERLAY");
        fx.harness.tui.overlay_unfocus(&overlay_handle, None);
        let after_unfocus = fx.focused_of("OVERLAY");
        fx.send("x", "OVERLAY");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "overlayFocused": overlay_focused,
                "afterUnfocus": after_unfocus,
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "handleFocused": fx.harness.tui.overlay_is_focused(&overlay_handle),
            }),
            FOCUS_UNFOCUS_NULL_PRE_FOCUS,
        );
        fx.stop();
    }
}

/// overlay-non-capturing.test.ts "focus cycle prevention".
#[test]
fn focus_cycle_prevention_scenarios() {
    let _tui_test_lock = test_lock();
    // toggle focus between non-capturing overlays then unfocus returns to editor
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let a_handle = fx.show(
            "A",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        let b_handle = fx.show(
            "B",
            Some(OverlayOptions {
                non_capturing: true,
                ..Default::default()
            }),
        );
        fx.harness.tui.overlay_focus(&a_handle);
        fx.harness.tui.overlay_focus(&b_handle);
        fx.harness.tui.overlay_focus(&a_handle);
        fx.harness.tui.overlay_unfocus(&a_handle, None);
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "editor": fx.focused_of("editor"),
                "a": fx.focused_of("A"),
                "b": fx.focused_of("B"),
            }),
            FOCUS_TOGGLE_CYCLE,
        );
        fx.stop();
    }
    // explicit unfocus target supports cycling between three overlays
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let a_handle = fx.show("A", None);
        let b_handle = fx.show("B", None);
        let c_handle = fx.show("C", None);
        fx.harness.tui.overlay_focus(&a_handle);
        fx.send("a", "A");
        render_and_flush(&mut fx.harness);
        fx.harness.tui.overlay_focus(&b_handle);
        fx.send("b", "B");
        render_and_flush(&mut fx.harness);
        fx.harness.tui.overlay_focus(&c_handle);
        fx.send("c", "C");
        render_and_flush(&mut fx.harness);
        fx.harness.tui.overlay_unfocus(
            &c_handle,
            Some(OverlayUnfocusOptions {
                target: Some(fx.component("editor")),
            }),
        );
        fx.send("e", "editor");
        render_and_flush(&mut fx.harness);
        fx.harness.tui.overlay_focus(&a_handle);
        fx.send("A", "A");
        render_and_flush(&mut fx.harness);
        fx.harness.tui.overlay_unfocus(
            &a_handle,
            Some(OverlayUnfocusOptions {
                target: Some(fx.component("editor")),
            }),
        );
        fx.send("E", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "aInputs": fx.inputs_of("A"),
                "bInputs": fx.inputs_of("B"),
                "cInputs": fx.inputs_of("C"),
                "editor": fx.focused_of("editor"),
                "editorInputs": fx.inputs_of("editor"),
            }),
            FOCUS_EXPLICIT_TARGETS_CYCLE,
        );
        fx.stop();
    }
    // explicit null unfocus target clears focus without restoring overlays
    {
        let mut fx = FocusFixture::plain();
        fx.start();
        let overlay_handle = fx.show("OVERLAY", None);
        fx.harness.tui.overlay_unfocus(
            &overlay_handle,
            Some(OverlayUnfocusOptions { target: None }),
        );
        fx.send("x", "OVERLAY");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "overlayInputs": fx.inputs_of("OVERLAY"),
                "handleFocused": fx.harness.tui.overlay_is_focused(&overlay_handle),
            }),
            FOCUS_NULL_UNFOCUS_TARGET,
        );
        fx.stop();
    }
    // hiding focused overlay falls back to next visual-frontmost overlay
    {
        let mut fx = FocusFixture::with_editor();
        fx.start();
        let a_handle = fx.show("A", None);
        let b_handle = fx.show("B", None);
        fx.show("C", None);
        fx.harness.tui.overlay_focus(&a_handle);
        fx.harness.tui.overlay_focus(&b_handle);
        fx.harness.tui.overlay_set_hidden(&b_handle, true);
        fx.send("x", "editor");
        render_and_flush(&mut fx.harness);
        assert_oracle_json(
            json!({
                "aInputs": fx.inputs_of("A"),
                "cInputs": fx.inputs_of("C"),
                "a": fx.focused_of("A"),
            }),
            FOCUS_HIDDEN_FALLS_TO_FRONTMOST,
        );
        fx.stop();
    }
}

fn visual_order_harness() -> Harness {
    let mut harness = make_harness(20, 6);
    harness.tui.add_child(ComponentHandle::new(EmptyContent));
    harness.tui.start();
    harness
}

fn show_static_overlay(harness: &mut Harness, line: &str, non_capturing: bool) -> OverlayHandle {
    harness.tui.show_overlay(
        ComponentHandle::new(StaticLines {
            lines: vec![line.to_string()],
            inputs: Vec::new(),
        }),
        Some(OverlayOptions {
            row: Some(SizeValue::Number(0.0)),
            col: Some(SizeValue::Number(0.0)),
            width: Some(SizeValue::Number(1.0)),
            non_capturing,
            ..Default::default()
        }),
    )
}

fn assert_visual_order(actual: serde_json::Value, expected: &str) {
    assert_oracle_json(actual, expected);
}

/// overlay-non-capturing.test.ts "rendering order".
#[test]
fn overlay_visual_order_scenarios() {
    let _tui_test_lock = test_lock();
    // focus() on already-focused overlay bumps visual order
    {
        let mut harness = visual_order_harness();
        let a_handle = show_static_overlay(&mut harness, "A", true);
        show_static_overlay(&mut harness, "B", true);
        render_and_flush(&mut harness);
        let first = viewport_of(&harness)[0].clone();
        harness.tui.overlay_focus(&a_handle);
        render_and_flush(&mut harness);
        let second = viewport_of(&harness)[0].clone();
        assert_visual_order(
            json!({ "first": first, "second": second }),
            FOCUS_VISUAL_ORDER_BUMP,
        );
        harness.tui.stop(TuiStopOptions::default());
        settle(&mut harness);
    }
    // default rendering order follows creation order
    {
        let mut harness = visual_order_harness();
        show_static_overlay(&mut harness, "A", true);
        show_static_overlay(&mut harness, "B", true);
        render_and_flush(&mut harness);
        assert_visual_order(
            json!({ "first": viewport_of(&harness)[0].clone() }),
            FOCUS_VISUAL_ORDER_CREATION,
        );
        harness.tui.stop(TuiStopOptions::default());
        settle(&mut harness);
    }
    // focus() on lower overlay renders it on top
    {
        let mut harness = visual_order_harness();
        let lower = show_static_overlay(&mut harness, "A", true);
        show_static_overlay(&mut harness, "B", true);
        render_and_flush(&mut harness);
        let before = viewport_of(&harness)[0].clone();
        harness.tui.overlay_focus(&lower);
        render_and_flush(&mut harness);
        let after = viewport_of(&harness)[0].clone();
        assert_visual_order(
            json!({ "before": before, "after": after }),
            FOCUS_VISUAL_ORDER_LOWER_FOCUS,
        );
        harness.tui.stop(TuiStopOptions::default());
        settle(&mut harness);
    }
    // focusing middle overlay places it on top preserving relative order
    {
        let mut harness = visual_order_harness();
        show_static_overlay(&mut harness, "A", true);
        let middle = show_static_overlay(&mut harness, "B", true);
        let top = show_static_overlay(&mut harness, "C", true);
        render_and_flush(&mut harness);
        let s0 = viewport_of(&harness)[0].clone();
        harness.tui.overlay_focus(&middle);
        render_and_flush(&mut harness);
        let s1 = viewport_of(&harness)[0].clone();
        harness.tui.overlay_hide(&middle);
        render_and_flush(&mut harness);
        let s2 = viewport_of(&harness)[0].clone();
        harness.tui.overlay_hide(&top);
        render_and_flush(&mut harness);
        let s3 = viewport_of(&harness)[0].clone();
        assert_visual_order(
            json!({ "s0": s0, "s1": s1, "s2": s2, "s3": s3 }),
            FOCUS_VISUAL_ORDER_MIDDLE,
        );
        harness.tui.stop(TuiStopOptions::default());
        settle(&mut harness);
    }
    // capturing overlay hidden and shown again renders on top after unhide
    {
        let mut harness = visual_order_harness();
        show_static_overlay(&mut harness, "A", true);
        let capturing = show_static_overlay(&mut harness, "B", false);
        render_and_flush(&mut harness);
        let s0 = viewport_of(&harness)[0].clone();
        harness.tui.overlay_set_hidden(&capturing, true);
        show_static_overlay(&mut harness, "C", true);
        render_and_flush(&mut harness);
        let s1 = viewport_of(&harness)[0].clone();
        harness.tui.overlay_set_hidden(&capturing, false);
        render_and_flush(&mut harness);
        let s2 = viewport_of(&harness)[0].clone();
        assert_visual_order(
            json!({ "s0": s0, "s1": s1, "s2": s2 }),
            FOCUS_VISUAL_ORDER_UNHIDE,
        );
        harness.tui.stop(TuiStopOptions::default());
        settle(&mut harness);
    }
    // unfocus() does not change visual order until another overlay is focused
    {
        let mut harness = visual_order_harness();
        let a = show_static_overlay(&mut harness, "A", true);
        let b = show_static_overlay(&mut harness, "B", true);
        render_and_flush(&mut harness);
        let s0 = viewport_of(&harness)[0].clone();
        harness.tui.overlay_focus(&a);
        render_and_flush(&mut harness);
        let s1 = viewport_of(&harness)[0].clone();
        harness.tui.overlay_unfocus(&a, None);
        render_and_flush(&mut harness);
        let s2 = viewport_of(&harness)[0].clone();
        harness.tui.overlay_focus(&b);
        render_and_flush(&mut harness);
        let s3 = viewport_of(&harness)[0].clone();
        assert_visual_order(
            json!({ "s0": s0, "s1": s1, "s2": s2, "s3": s3 }),
            FOCUS_VISUAL_ORDER_UNFOCUS_KEEPS_ORDER,
        );
        harness.tui.stop(TuiStopOptions::default());
        settle(&mut harness);
    }
}
